import './../assets/css/login.css'; // Add this line
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';


const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const { email, password } = formData;
  const navigate = useNavigate();

  const onChange = e => setFormData({ ...formData, [e.target.name]: e.target.value });

  const onSubmit = async e => {
    e.preventDefault();
    // ... (inside the onSubmit function)

  try {
    const res = await axios.post('http://localhost:5000/api/auth/login', formData);
    console.log(res.data);
    localStorage.setItem('token', res.data.token);
    localStorage.setItem('role', res.data.role);

    if (res.data.role === 'admin') {
      navigate('/admin-dashboard');
    } else if (res.data.role === 'teacher') {
      navigate('/teacher-dashboard');
    }
  } catch (err) {
    // This is the updated code
    if (err.response) {
      console.error(err.response.data);
      alert(err.response.data.msg); // Use the message from the backend
    } else {
      console.error(err);
      alert('Network Error. Please try again.'); // A generic message for network failures
    }
  }
};

  return (
    <form onSubmit={onSubmit}>
      <div>
        <input
          type="email"
          placeholder="Email Address"
          name="email"
          value={email}
          onChange={onChange}
          required
        />
      </div>
      <div>
        <input
          type="password"
          placeholder="Password"
          name="password"
          value={password}
          onChange={onChange}
          minLength="6"
          required
        />
      </div>
      <button type="submit">Login</button>
    </form>
  );
};

export default Login;
